package com.vandorlabs.neoforge.canopy;

import com.google.gson.*;
import com.vandorlabs.canopy.*;
import java.nio.file.*;

/** Independent actual Source analytic extrema, including stationary-axis and reversed-interval records. */
public final class CanopySweepChecks {
    public static void main(String[] args)throws Exception{long checks=0,boxes=0,drift=0;double maxError=0,maxUlps=0,maxExpansion=0;int profiles=0;long predicates=0,predicateDifferences=0;var predicatesReader=Files.newBufferedReader(Path.of(args[2]));var queryHeader=JsonParser.parseString(predicatesReader.readLine()).getAsJsonObject();var queries=new java.util.ArrayList<CanopyPhysics.Box>();for(var raw:queryHeader.getAsJsonArray("queries")){var words=raw.getAsJsonArray();double[] v=new double[6];for(int i=0;i<6;i++)v[i]=Double.longBitsToDouble(Long.parseLong(words.get(i).getAsString()));queries.add(new CanopyPhysics.Box(v[0],v[1],v[2],v[3],v[4],v[5]));}var inputs=new java.util.HashMap<String,java.util.List<CanopyFace>>();try(var in=Files.newBufferedReader(Path.of(args[1]))){for(String line;(line=in.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();var faces=new java.util.ArrayList<CanopyFace>();for(var raw:row.getAsJsonArray("faces")){var face=raw.getAsJsonObject();var words=face.getAsJsonArray("points");CanopyPoint[] points=new CanopyPoint[words.size()/3];double[][] uv=new double[points.length][2];for(int i=0;i<points.length;i++)points[i]=new CanopyPoint(Double.longBitsToDouble(Long.parseLong(words.get(i*3).getAsString())),Double.longBitsToDouble(Long.parseLong(words.get(i*3+1).getAsString())),Double.longBitsToDouble(Long.parseLong(words.get(i*3+2).getAsString())));faces.add(new CanopyFace(points,uv,"probe","probe",face.get("group").getAsString(),false,false,false));}inputs.put(row.get("id").getAsString()+":"+row.get("profile").getAsInt(),java.util.List.copyOf(faces));}}
        try(var reader=Files.newBufferedReader(Path.of(args[0]))){for(String line;(line=reader.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();String kind=row.get("id").getAsString();var settings=NativeCanopySettings.read(CanopySettingsChecks.tags(row.getAsJsonObject("settings")));int width=row.get("width").getAsInt(),facing=row.get("facing").getAsInt();var faces=NativeCanopyModels.builtin().geometry(kind,width,row.get("mask").getAsInt(),row.get("roof").getAsInt(),row.get("centered").getAsBoolean(),settings.data());var sourceFaces=inputs.get(kind+":"+row.get("profile").getAsInt());for(int f=0;f<faces.size();f++){if(faces.get(f).points()!=sourceFaces.get(f).points())throw new AssertionError("Source face point count");for(int p=0;p<faces.get(f).points();p++){var a=faces.get(f).vertex(p);var b=sourceFaces.get(f).vertex(p);if(Double.doubleToRawLongBits(a.x)!=Double.doubleToRawLongBits(b.x)||Double.doubleToRawLongBits(a.y)!=Double.doubleToRawLongBits(b.y)||Double.doubleToRawLongBits(a.z)!=Double.doubleToRawLongBits(b.z))throw new AssertionError("Source sweep base geometry "+kind+"/"+profiles+" face="+f+" point="+p+" expected="+b.x+","+b.y+","+b.z+" actual="+a.x+","+a.y+","+a.z);}}var wanted=row.getAsJsonArray("boxes");if(faces.size()!=wanted.size())throw new AssertionError("Canopy sweep authored face count "+kind+"/"+profiles);var interval=new CanopySweepBounds.Context(kind,width,settings.data(),row.get("from").getAsDouble(),row.get("to").getAsDouble());var outwardBoxes=new java.util.ArrayList<CanopyPhysics.Box>();for(int i=0;i<faces.size();i++){var local=interval.bounds(faces.get(i));var box=CanopySweepBounds.world(local,facing,-17,84,35);var outward=CanopySweepBounds.conservativeWorld(interval,local,facing,-17,84,35);outwardBoxes.add(outward);double[] outer={outward.minX,outward.minY,outward.minZ,outward.maxX,outward.maxY,outward.maxZ};int uncertain=CanopySweepBounds.worldAxes(interval.uncertainAxes(),facing);double[] values={box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ};var expected=wanted.get(i).getAsJsonArray();for(int at=0;at<6;at++){long actual=Double.doubleToRawLongBits(values[at]),source=Long.parseLong(expected.get(at).getAsString());double sourceValue=Double.longBitsToDouble(source);if(actual!=source){drift++;double error=Math.abs(values[at]-sourceValue);maxError=Math.max(maxError,error);maxUlps=Math.max(maxUlps,error/Math.ulp(sourceValue));if((uncertain&(1<<(at%3)))==0)throw new AssertionError("Stationary hinge axis drift "+kind+"/"+profiles+"/"+at);if(error>Math.ulp(sourceValue))throw new AssertionError("Unbounded sweep drift");}if(at<3?outer[at]>sourceValue:outer[at]<sourceValue)throw new AssertionError("Moving-axis outward bound misses Source "+kind+"/"+profiles+"/"+i+"/"+at);maxExpansion=Math.max(maxExpansion,Math.abs(outer[at]-values[at]));checks++;}boxes++;}var index=new CanopyBoundsIndex(outwardBoxes);var expectedHits=java.util.BitSet.valueOf(java.util.Base64.getDecoder().decode(predicatesReader.readLine()));for(int q=0;q<queries.size();q++){boolean actual=index.intersects(queries.get(q)),source=expectedHits.get(q);if(source&&!actual)throw new AssertionError("Source Ramp intersection missed "+kind+"/"+profiles+"/"+q);if(actual!=source)predicateDifferences++;predicates++;}profiles++;}}predicatesReader.close();
        if(profiles!=4928||boxes!=2450196)throw new AssertionError("Canopy sweep corpus coverage "+profiles+"/"+boxes);System.out.println("Canopy swept bounds PASS profiles="+profiles+" boxes="+boxes+" comparedWords="+checks+" driftWords="+drift+" maxAbsoluteDrift="+maxError+" maxUlpDrift="+maxUlps+" maxMovingExpansion="+maxExpansion+" rampPredicates="+predicates+" conservativeExtraContacts="+predicateDifferences);if(predicateDifferences!=0)throw new AssertionError("Conservative predicate differences require review "+predicateDifferences);
    }
}
